<template>
  <div>
    <f-toggle size="xs"
      v-model="user_settings[dual_monitor_mode_setting]"
      :label="$t('dual_monitor_mode')"
      :left-label="true"
      @update:model-value="
        (val: boolean) => {
          setUserPreference(dual_monitor_mode_setting, val);
        }
      "
    />
  </div>

  <div class="row" v-if="user_settings[dual_monitor_mode_setting]">
    <q-option-group
      v-model="user_settings[monitor_preference]"
      :options="options"
      color="primary"
      inline
      @update:model-value="
        (val: any) => {
          setUserPreference(monitor_preference, val);
        }
      "
    />
  </div>

  <q-inner-loading :showing="loading || loading_settings">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
    props: [],
  components: {},
  data() {
    return {
      monitor_preference: CONSTANTS.monitor_preference,
      dual_monitor_mode_setting: CONSTANTS.dual_monitor_mode_setting,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (
          newVal == false &&
          oldVal == true &&
          !this.user_settings[this.dual_monitor_mode_setting]
        ) {
          this.user_settings[this.dual_monitor_mode_setting] = false;
        }
      },
    },
  },
  async mounted() {
    // if(!this.user_settings[this.dual_monitor_mode_setting]) {
    //   this.user_settings[this.dual_monitor_mode_setting] = false
    //   return;
    // }
    // const response = await userApiService.getUserPreference({key: this.monitor_preference});
    // this.user_settings[this.monitor_preference] = response;
  },
  methods: {
    async setUserPreference(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        await this.setUserPreferences(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { setUserPreferences } = settings_store;
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    return {
      setUserPreferences,
      user_settings,
      loading_settings,
      loading: ref(false),
      options: [
        {
          label: 'Monitor 1',
          value: 'monitor_1',
        },
        {
          label: 'Monitor 2',
          value: 'monitor_2',
        },
      ],
    };
  },
});
</script>

<style lang="scss" scoped></style>
