<template>
  <q-select
    dense
    outlined
    options-dense
    :loading="language_origins_loading || loading_settings"
    v-model="user_settings[amount_format_setting]"
    :options="format_origins"
    emit-value
    map-options
    :label="$t('amount_format')"
    @update:model-value="
      (val: any) => {
        updateUserPreferences(amount_format_setting, val);
      }
    "
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label>{{ scope.opt.label }}</q-item-label>
          <q-tooltip v-if="scope.opt.description">
            <span v-html="scope.opt.description"></span
          ></q-tooltip>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore, useLangOriginDropdownStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { amount_format_setting } from 'src/constants';
import { isUndefinedOrNull } from 'src/utils/general';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
    props: [],
  components: {},
  mounted: function () {
    this.init();
  },
  data() {
    return {
      amount_format_setting,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.init();
        }
      },
    },
  },
  methods: {
    updateUserPreferences(setting: string, value: string) {
      try {
        this.setUserPreferences(setting, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    init() {
      if (this.loading_settings) return;

      if (isUndefinedOrNull(this.user_settings[this.amount_format_setting])) {
        this.user_settings[this.amount_format_setting] = '';
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { setUserPreferences } = settings_store;

    const language_origin_dropdown = useLangOriginDropdownStore();
    const {
      format_origins,
      language_origins_loading,
      language_origins_loaded,
    } = storeToRefs(language_origin_dropdown);

    return {
      loading_settings,
      setUserPreferences,
      format_origins,
      language_origins_loading,
      language_origins_loaded,
      user_settings,
    };
  },
});
</script>
