import type { dynamicObj, cstmOptions } from 'src/pages/assets';
import { api, getAuthorizationToken } from 'pages/APIs';
import axios, { AxiosResponse } from 'axios';
import { encodeQueryData } from 'src/utils/general';
import { useSubscriptionStore } from 'src/store/main';
export default {
  methods: {
    async getWorkflowSettings() {
      try {
        const subscription_store = useSubscriptionStore();
        if (!subscription_store.hasAppsSubscription) {
          return { success: false, message: 'no_subscribed' };
        }

        const settings = await this.getSettingsFromWorkflowServer();
        // go time
        if (settings.active === true && settings.ready === true) {
          settings.message = 'ready';
        }

        // creation in progress
        if (settings.active === true && settings.ready === false) {
          settings.message = 'in_progress';
        }

        // no n8n
        if (settings.active === false && settings.ready === false) {
          settings.message = 'new';
        }
        return settings;
      } catch (error: any) {
        this.handleN8NErrors(error);
      } finally {
      }
      return { success: false, message: 'new' };
    },
    handleN8NErrors(error: any) {
      let msg = '';

      if (
        error != null &&
        typeof error == 'object' &&
        error.hasOwnProperty('message')
      ) {
        msg = error.message;
      }

      if (error && error.response && error.response.data) {
        if (error.response.data.hasOwnProperty('message')) {
          msg = error.response.data.message;
        }

        if (error.response.data.hasOwnProperty('error_description')) {
          msg = error.response.data.error_description;
        }

        if (error.response.status === 403) {
          msg = error.response.data + '. Please contact administrator';
        }
      }
      throw { success: false, message: msg };
    },

    subscriptionError() {
      return 'no_subscribed';
    },

    async getSettingsFromWorkflowServer() {
      const token: string = await getAuthorizationToken();
      const data = { app: 'workflow' };
      const querystring = encodeQueryData(data);
      const response = await axios.get(
        api.workflow_get_settings + '?' + querystring,
        {
          headers: {
            Authorization: token,
          },
        },
      );

      const result = response.data;
      if (
        !result ||
        !result.hasOwnProperty('success') ||
        !result.hasOwnProperty('url') ||
        !result.hasOwnProperty('active') ||
        !result.hasOwnProperty('ready') ||
        !result.hasOwnProperty('subdomain') ||
        !result.hasOwnProperty('password')
      ) {
        throw { error_code: 'settings_api_fail' };
      }

      const return_res = {
        success: response.data.success,
        url: response.data.url,
        active: response.data.active,
        ready: response.data.ready,
        subdomain: response.data.subdomain,
        password: response.data.password,
      } as { [k: string]: any };
      return return_res;
    },
    async triggerNewWorkflowForUser(settings: dynamicObj) {
      const token: string = await getAuthorizationToken();
      const response = await axios.post(
        api.workflow_actions,
        {
          create: settings.create.toString(),
          subdomain_prefix: settings.domain_name.toLowerCase(),
        },
        {
          headers: {
            'X-API-KEY': token.replace('Bearer ', ''),
            'Content-Type': 'application/json',
            accept: 'application/json',
          },
        },
      );

      if (response.data.success !== true) {
        throw { message: response.data.message };
      }

      return true;
    },
    getN8NerrorMessagesList() {
      const errors_list: cstmOptions = {
        no_subscribed:
          'You need to have a doc2app subscription to access workflows',
        workflow_url_not_found:
          'Url for the workflow is missing. Please contact administrator',
        workflow_in_progress:
          'Workflow creation is in-progress. This might take a while',
      };

      return errors_list;
    },
  },
};
