<template>
  <q-select
    :loading="date_pattern_loading || loading_settings"
    dense
    outlined
    options-dense
    v-model="user_settings[date_pattern_setting]"
    :options="date_pattern_list"
    emit-value
    map-options
    :label="$t('date_pattern')"
    @update:model-value="
      (val: any) => {
        updateUserPreferences(date_pattern_setting, val);
      }
    "
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label>{{ scope.opt.label }}</q-item-label>
          <q-tooltip v-if="scope.opt.description">
            <span v-html="scope.opt.description"></span
          ></q-tooltip>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { isUndefinedOrNull } from 'src/utils/general';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { date_pattern_setting } from 'src/constants';
import { useSettingStore, useDatePatternDropdownStore } from 'src/store/main';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
    props: [],
  components: {},
  mounted: function () {
    this.init();
  },
  data() {
    return {
      date_pattern_setting,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.init();
        }
      },
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { setUserPreferences } = settings_store;

    const date_pattern_dropdown = useDatePatternDropdownStore();
    const { date_pattern_list, date_pattern_loading, date_pattern_loaded } =
      storeToRefs(date_pattern_dropdown);
    return {
      setUserPreferences,
      user_settings,
      loading_settings,
      date_pattern_list,
      date_pattern_loading,
      date_pattern_loaded,
    };
  },
  methods: {
    updateUserPreferences(setting: string, value: string) {
      try {
        this.setUserPreferences(setting, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    init() {
      if (this.loading_settings) return;

      if (isUndefinedOrNull(this.user_settings[this.date_pattern_setting])) {
        this.user_settings[this.date_pattern_setting] = '';
      }
    },
  },
});
</script>

<style lang="scss" scoped></style>
